<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';
 import {romeToUtc} from './rome.js';
 import LocationPicker from './LocationPicker.svelte';
 export let tripId:number;
 export let initialOutcome:string;
 export let onChanged:()=>void;
 type Rod={id:number,name:string}; type Interval={id:number,rod_id:number,starts_at:string,ends_at:string,rig:string,bait:string,pause_minutes:number|null,ineffective_minutes:number|null}; type Catch={id:number,occurred_at:string,species:string,uncertain:boolean,length_cm:number|null,weight_g:number|null,weight_estimated:boolean,disposition:string}; type Observation={id:number,occurred_at:string,kind:string,notes:string}; type Position={id:number,role:string,latitude:number,longitude:number,origin:string,accuracy_m:number|null}; type Details={rods:Rod[],intervals:Interval[],catches:Catch[],observations:Observation[],positions:Position[]};
 let data:Details={rods:[],intervals:[],catches:[],observations:[],positions:[]}; let positionRole='station',latitude='',longitude='',accuracy='',positionOrigin='manual',showMap=false; let observedAt='', observationKind='mare', observationNotes=''; let error=''; let rodName=''; let rodId=0; let start='',end='',rig='',bait='',pause='',ineffective=''; let species='',caughtAt='',length='',weight='',uncertain=false,weightEstimated=false,disposition='unknown'; let outcome='incomplete';
 let loadedId=0;
 $: if(tripId!==loadedId){loadedId=tripId;outcome=initialOutcome;load()}
 async function load(){try{data=await invoke('trip_details',{tripId}); error=''; if(!data.rods.some(x=>x.id===rodId))rodId=data.rods[0]?.id || 0;}catch{error='Impossibile caricare i dettagli.'}}
 async function action(command:string,args:Record<string,unknown>){try{await invoke(command,args); await load();onChanged();}catch(e){error=typeof e==='object'&&e!==null&&'message' in e?String(e.message):'Impossibile salvare i dati.';}}
 async function saveObservation(){if(!observedAt){error='Inserisci l’ora dell’osservazione.';return} try{await action('add_observation',{observation:{trip_id:tripId,occurred_at:utc(observedAt),kind:observationKind,notes:observationNotes}})}catch(e){error=e instanceof Error?e.message:'Ora non valida.'}}
 function utc(s:string){return romeToUtc(s)}
 function display(s:string){return new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(s))}
 async function remove(kind:string,id:number) { if(!confirm('Eliminare questo elemento? L’operazione non si può annullare.'))return; await action('delete_diary_item',{tripId,itemId:id,kind}); }
 function positionFromMap(lat:number,lon:number){latitude=lat.toFixed(6);longitude=lon.toFixed(6);accuracy='';positionOrigin='map'}
 function locate(){if(!navigator.geolocation){error='Geolocalizzazione non disponibile.';return}navigator.geolocation.getCurrentPosition(p=>{latitude=String(p.coords.latitude);longitude=String(p.coords.longitude);accuracy=String(Math.round(p.coords.accuracy));positionOrigin='gps';error=''},()=>{error='Posizione non disponibile o permesso non concesso.'},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
 async function savePosition(){if(!latitude.trim()||!longitude.trim()){error='Inserisci latitudine e longitudine.';return}await action('save_position',{position:{trip_id:tripId,role:positionRole,latitude:Number(latitude),longitude:Number(longitude),origin:positionOrigin,accuracy_m:accuracy===''?null:Number(accuracy)}})}
 async function saveRod(){await action('add_rod',{tripId,name:rodName});rodName=''}
 async function saveInterval(){if(!start||!end||!rodId){error='Seleziona canna, inizio e fine.';return} try{await action('add_interval',{interval:{rod_id:Number(rodId),starts_at:utc(start),ends_at:utc(end),rig,bait,pause_minutes:pause === '' ? null : Number(pause),ineffective_minutes:ineffective === '' ? null : Number(ineffective)}})}catch(e){error=e instanceof Error?e.message:'Ora non valida.'}}
 async function saveCatch(){if(!caughtAt||!species.trim()){error='Inserisci specie e ora.';return}try{await action('add_catch',{catch:{trip_id:tripId,occurred_at:utc(caughtAt),species,uncertain,length_cm:length?Number(length):null,weight_g:weight?Number(weight):null,weight_estimated:weightEstimated,disposition}})}catch(e){error=e instanceof Error?e.message:'Ora non valida.'}}
</script>
<div class="trip-details">
<h3>Dettagli dell’uscita</h3><p class="source">Gli orari sono riferiti a Roma.</p>
{#if error}<p class="error" role="alert">{error}</p>{/if}
<div class="detail-columns"><section><h4>Canne e intervalli</h4><form on:submit|preventDefault={saveRod} class="compact-form"><label>Nome della canna<input bind:value={rodName} required placeholder="Canna 1"></label><button type="submit">Aggiungi canna</button></form>
{#each data.rods as rod}<div class="detail-row"><strong>{rod.name}</strong> <button type="button" on:click={() => remove('rod',rod.id)}>Elimina canna e intervalli</button></div>{/each}
{#if data.rods.length}<form on:submit|preventDefault={saveInterval} class="compact-form"><label>Canna<select bind:value={rodId}>{#each data.rods as rod}<option value={rod.id}>{rod.name}</option>{/each}</select></label><label>Inizio<input type="datetime-local" bind:value={start} required></label><label>Fine<input type="datetime-local" bind:value={end} required></label><label>Montatura<input bind:value={rig}></label><label>Esca<input bind:value={bait}></label><label>Minuti di pausa <span>facoltativo</span><input type="number" min="0" step="1" bind:value={pause}></label><label>Minuti con esca inefficace, escluse le pause <span>facoltativo</span><input type="number" min="0" step="1" bind:value={ineffective}></label><button type="submit">Aggiungi intervallo</button></form>{/if}
{#each data.intervals as interval}<div class="detail-row"><strong>{data.rods.find(r=>r.id===interval.rod_id)?.name}</strong><br>{display(interval.starts_at)} – {display(interval.ends_at)}<br>{interval.rig || 'Montatura non indicata'} · {interval.bait || 'Esca non indicata'}<br>Pause: {interval.pause_minutes === null ? 'non registrate' : `${interval.pause_minutes} min`}; esca inefficace: {interval.ineffective_minutes === null ? 'non registrata' : `${interval.ineffective_minutes} min`}.<br>Tempo effettivo: {interval.pause_minutes === null || interval.ineffective_minutes === null ? 'non determinabile' : `${Math.max(0,(new Date(interval.ends_at).getTime()-new Date(interval.starts_at).getTime())/60000-interval.pause_minutes-interval.ineffective_minutes)} min`} <button type="button" on:click={() => remove('interval',interval.id)}>Elimina</button></div>{/each}</section>
<section><h4>Catture</h4><form on:submit|preventDefault={saveCatch} class="compact-form"><label>Specie<input bind:value={species} required></label><label><input type="checkbox" bind:checked={uncertain}> Identificazione incerta</label><label>Ora<input type="datetime-local" bind:value={caughtAt} required></label><label>Lunghezza in cm <span>facoltativo</span><input type="number" min="0.1" step="0.1" bind:value={length}></label><label>Peso in g <span>facoltativo</span><input type="number" min="0.1" step="0.1" bind:value={weight}></label><label><input type="checkbox" bind:checked={weightEstimated}> Peso stimato</label><label>Esito<select bind:value={disposition}><option value="unknown">Non indicato</option><option value="released">Rilasciato</option><option value="kept">Trattenuto</option></select></label><button type="submit">Aggiungi cattura</button></form>{#each data.catches as item}<div class="detail-row"><strong>{item.species}{item.uncertain ? ' (incerta)' : ''}</strong><br>{display(item.occurred_at)} · {item.disposition==='released'?'rilasciato':item.disposition==='kept'?'trattenuto':'esito non indicato'}{#if item.length_cm} · {item.length_cm} cm{/if}{#if item.weight_g} · {item.weight_g} g{item.weight_estimated?' stimati':''}{/if} <button type="button" on:click={() => remove('catch',item.id)}>Elimina</button></div>{/each}</section></div>
<section class="observations"><h4>Posizioni personali</h4><p class="source">La posizione in cui ti trovi è distinta dalla zona di lancio. Questi punti rimangono nel diario e non sono postazioni scientifiche verificate.</p><form class="compact-form" on:submit|preventDefault={savePosition}><label>Tipo<select bind:value={positionRole}><option value="station">Postazione</option><option value="cast">Zona di lancio</option></select></label><label>Latitudine<input type="number" min="-90" max="90" step="any" bind:value={latitude} on:input={() => {positionOrigin='manual';accuracy=''}} required></label><label>Longitudine<input type="number" min="-180" max="180" step="any" bind:value={longitude} on:input={() => {positionOrigin='manual';accuracy=''}} required></label><label>Accuratezza dichiarata in metri <span>facoltativa</span><input type="number" min="0" step="any" bind:value={accuracy}></label><p class="source">Origine: {positionOrigin==='gps'?'geolocalizzazione':positionOrigin==='map'?'clic sulla mappa':'coordinate inserite'}. Per cambiare l’origine, usa un metodo diverso.</p><button type="button" on:click={locate}>Usa geolocalizzazione</button><button type="button" on:click={() => showMap=!showMap}>{showMap?'Chiudi mappa':'Scegli sulla mappa'}</button>{#if showMap}<p class="source">La mappa contiene solo confini regionali: è indicativa e non permette di verificare accessi o dettagli della postazione. L’accuratezza del clic non è nota.</p><LocationPicker onPick={positionFromMap} />{/if}<button type="submit">Salva posizione</button></form>{#each data.positions as point}<div class="detail-row"><strong>{point.role==='station'?'Postazione':'Zona di lancio'}</strong>: {point.latitude}, {point.longitude}<br>Origine: {point.origin==='gps'?'geolocalizzazione':point.origin==='map'?'mappa':'coordinate inserite'}; accuratezza: {point.accuracy_m===null?'non dichiarata':`${point.accuracy_m} m`} <button type="button" on:click={() => remove('position',point.id)}>Elimina</button></div>{/each}</section>
<section class="observations"><h4>Osservazioni sul posto</h4><form class="compact-form" on:submit|preventDefault={saveObservation}><label>Tipo<select bind:value={observationKind}><option value="mare">Mare</option><option value="corrente">Corrente</option><option value="alghe">Alghe</option><option value="torbidita">Torbidità</option><option value="deriva_piombo">Deriva del piombo</option><option value="groviglio">Groviglio</option><option value="esca">Condizione dell’esca</option><option value="altro">Altro</option></select></label><label>Ora<input type="datetime-local" bind:value={observedAt} required></label><label>Appunti<input bind:value={observationNotes} placeholder="Cosa hai osservato?"></label><button type="submit">Aggiungi osservazione</button></form>{#each data.observations as item}<div class="detail-row"><strong>{item.kind.replaceAll('_',' ')}</strong> · {display(item.occurred_at)}{#if item.notes}<br>{item.notes}{/if} <button type="button" on:click={() => remove('observation',item.id)}>Elimina</button></div>{/each}</section>
<form class="outcome-form" on:submit|preventDefault={() => action('set_outcome',{tripId,outcome})}><label>Stato dell’uscita <select bind:value={outcome}><option value="incomplete">Registrazione incompleta</option><option value="zero">Nessuna cattura</option><option value="catches">Catture registrate</option></select></label><button type="submit">Aggiorna esito</button></form>
</div>
